]}

Atos 22 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Aos pés de quem Paulo diz ter sido instruído em Jerusalém?","o":["Ananias","Gamaliel","Estêvão","O sumo sacerdote"],"c":1,"v":3,"e":"No versículo 3, Paulo diz que foi instruído aos pés de Gamaliel, segundo a exatidão da lei."},
 {"t":"multipla","p":"Em que hora do dia a grande luz do céu brilhou ao redor de Paulo perto de Damasco?","o":["Ao amanhecer","Ao entardecer","Quase ao meio-dia","À meia-noite"],"c":2,"v":6,"e":"No versículo 6, Paulo conta que a luz brilhou quase ao meio-dia, quando se aproximava de Damasco."},
 {"t":"multipla","p":"Quem disse a Paulo: \"Saulo, irmão, recebe novamente a vista\"?","o":["Ananias","Gamaliel","O centurião","Barnabé"],"c":0,"v":13,"e":"Nos versículos 12 e 13, Ananias, homem piedoso, foi até Paulo e lhe disse essas palavras."},
 {"t":"multipla","p":"Para onde o Senhor disse, no êxtase no templo, que enviaria Paulo?","o":["De volta a Tarso","Para longe, aos gentios","Para Damasco","Às sinagogas de Jerusalém"],"c":1,"v":21,"e":"No versículo 21, o Senhor diz: \"Vai, porque eu te enviarei para longe, aos gentios\"."},
 {"t":"multipla","p":"O que o tribuno ordenou que fizessem com Paulo depois dos gritos da multidão?","o":["Que fosse solto imediatamente","Que fosse levado a Damasco","Que fosse entregue aos sacerdotes","Que fosse levado à fortaleza e interrogado sob açoites"],"c":3,"v":24,"e":"No versículo 24, o tribuno manda levá-lo à fortaleza e interrogá-lo sob açoites para saber por que clamavam contra ele."},
