 {"t":"cv","p":"O comandante mandou que Paulo fosse acorrentado com duas correntes.","c":true,"v":33,"e":"O versículo 33 diz que o comandante ordenou que Paulo fosse acorrentado com duas correntes."},
 {"t":"cv","p":"Paulo disse ao comandante que era natural de Jerusalém.","c":false,"v":39,"e":"No versículo 39 Paulo diz que é judeu, natural de Tarso, cidade da Cilícia."},
