]}

Atos 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que os sacerdotes, o capitão do templo e os saduceus ficaram incomodados com Pedro e João?","o":["Porque ensinavam o povo e anunciavam a ressurreição dos mortos por meio de Jesus","Porque curaram um homem no sábado","Porque entraram no templo sem permissão","Porque recolhiam dinheiro do povo"],"c":0,"v":2,"e":"O versículo 2 diz que eles se incomodaram com o ensino ao povo e com a proclamação da ressurreição por meio de Jesus."},
 {"t":"multipla","p":"O que as autoridades perguntaram a Pedro e João no dia seguinte?","o":["Quem vos deu permissão para ensinar no templo?","Com que poder ou em nome de quem fizestes isto?","Onde está o corpo de Jesus?","Quem é o homem que foi curado?"],"c":1,"v":7,"e":"No versículo 7 as autoridades perguntam com que poder ou em nome de quem eles tinham feito aquilo."},
 {"t":"multipla","p":"Segundo Pedro, em nome de quem o homem enfermo foi curado?","o":["Em nome de Moisés","Em nome de Pedro e João","Em nome de Jesus Cristo, o Nazareno","Em nome do sumo sacerdote"],"c":2,"v":10,"e":"No versículo 10 Pedro declara que o homem foi curado em nome de Jesus Cristo, o Nazareno."},
 {"t":"multipla","p":"O que deixou as autoridades admiradas diante de Pedro e João?","o":["O grande conhecimento que tinham da Lei","A ousadia deles, mesmo sendo homens sem instrução e incultos","A quantidade de seguidores armados que os acompanhavam","A riqueza que haviam juntado"],"c":1,"v":13,"e":"O versículo 13 diz que ficaram admirados com a ousadia de homens sem instrução e reconheceram que tinham estado com Jesus."},
 {"t":"multipla","p":"O que as autoridades ordenaram a Pedro e João?","o":["Que saíssem de Jerusalém","Que pagassem uma multa ao templo","Que não entrassem mais no templo","Que não falassem nem ensinassem no nome de Jesus"],"c":3,"v":18,"e":"No versículo 18 eles ordenam que os apóstolos não falem nem ensinem, de maneira alguma, no nome de Jesus."},
 {"t":"cv","p":"As autoridades soltaram Pedro e João por causa do povo, que glorificava a Deus pelo que havia acontecido.","c":true,"v":21,"e":"O versículo 21 diz que os soltaram por causa do povo, pois todos glorificavam a Deus pelo que havia acontecido."},
 {"t":"cv","p":"Depois de orarem, os irmãos ficaram com medo e pararam de anunciar a palavra de Deus.","c":false,"v":31,"e":"O versículo 31 diz que o lugar tremeu, todos ficaram cheios do Espírito Santo e anunciavam a palavra com intrepidez."},
 {"t":"cv","p":"José, a quem os apóstolos chamaram de Barnabé, vendeu um campo e colocou o dinheiro aos pés dos apóstolos.","c":true,"v":37,"e":"O versículo 37 conta que Barnabé vendeu seu campo, trouxe o preço e o colocou aos pés dos apóstolos."}
]}

